-- loan_payments 갭 해소 (2026-08-24) — 자금 예측이 실만기·실상환과 정합하도록 스케줄 재생성
-- 실행: npx wrangler d1 execute webapp-production --remote --file docs/analysis/2026-08-24-loan-payments-schedule.sql
-- 대상: id4 개발기술(이자-only 12회차 -> OLS 실측 39회차, 12/21부터 원금 710만/월) · id19~22 선명 4건(0건 -> 실측 금리 기반)
-- 관행 유지: INTEREST_ONLY 는 만기 후에도 12개월 이자 지속(연장 전제, 기존 e1 절벽 대출과 동일) · 원금 일시상환 회차는 만들지 않는다
-- 멱등: 백업 IF NOT EXISTS 1회 · DELETE(SCHEDULED만) + INSERT 재실행 무해 · DONE/실적 행은 건드리지 않음
CREATE TABLE IF NOT EXISTS _bak_0824_loan_payments AS SELECT * FROM loan_payments WHERE loan_id IN (4,19,20,21,22);
DELETE FROM loan_payments WHERE loan_id IN (4,19,20,21,22) AND status='SCHEDULED';
